// The UK phrase demo carries its own JavaScript port of tools/gridcode/ukphrase.py.
// This runs that port against a fixture generated by the Python reference, so the
// two cannot drift. Regenerate with tools/gridcode/build_ukphrase_fixture.py.
import { readFileSync, writeFileSync, rmSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, '..', '..', 'demos', 'uk-phrase.html'), 'utf8');
const fixture = JSON.parse(readFileSync(join(here, 'fixture-ukphrase.json'), 'utf8'));

let bad = 0;
const fail = (msg) => { bad++; console.error(`  ${msg}`); };

// The demo embeds the three lists and the mask; the reference reads them from files.
for (const [name, file] of [['ADJECTIVES', 'adjective'], ['NOUNS', 'noun'], ['VERBS', 'verb']]) {
  const embedded = JSON.parse(html.match(new RegExp(`const ${name} = (\\[[^\\n]*\\]);`))[1]);
  const listed = readFileSync(join(here, '..', 'wordlist', `phrase-${file}.txt`), 'utf8')
    .trim().split('\n');
  if (embedded.join('\n') !== listed.join('\n'))
    fail(`the demo's ${file} list is not tools/wordlist/phrase-${file}.txt`);
}
const mask = html.match(/const MASK = '([^']*)';/)[1];
if (mask !== readFileSync(join(here, 'uk-mask.txt'), 'utf8').trim())
  fail("the demo's mask is not tools/gridcode/uk-mask.txt");

const start = html.indexOf('const ADJECTIVES = ');
const src = html.slice(start, html.indexOf('// --- map ---'))
  + '\nexport { cellAt, centreOf, encode, decodeCell, scramble, unscramble, parsePhrase,'
  + ' K, CHECK, SIZES };';
const tmp = join(here, `.check-ukphrase-demo-${process.pid}.mjs`);
writeFileSync(tmp, src);
let mod;
try { mod = await import(pathToFileURL(tmp).href); } finally { rmSync(tmp, { force: true }); }

if (mod.K !== fixture.k) fail(`K: js ${mod.K} vs py ${fixture.k}`);
if (mod.CHECK !== fixture.check) fail(`check: js ${mod.CHECK} vs py ${fixture.check}`);
if (mod.SIZES.join(',') !== fixture.sizes.join(','))
  fail(`sizes: js ${mod.SIZES} vs py ${fixture.sizes}`);

for (const [v, n] of fixture.scramble) {
  if (mod.scramble(v) !== n) fail(`SCRAMBLE ${v}: js ${mod.scramble(v)} vs py ${n}`);
  if (mod.unscramble(n) !== v) fail(`UNSCRAMBLE ${n}: js ${mod.unscramble(n)} vs py ${v}`);
}

for (const c of fixture.points) {
  const cell = mod.cellAt(c.lat, c.lng);
  if (cell !== c.cell) fail(`CELL ${c.lat},${c.lng}: js ${cell} vs py ${c.cell}`);
  const got = mod.encode(c.lat, c.lng);
  if (got.join(' ') !== c.words.join(' '))
    fail(`MISMATCH ${c.lat},${c.lng}: js ${got.join(' ')} vs py ${c.words.join(' ')}`);
  const [la, lo] = mod.centreOf(c.cell);
  if (Math.abs(la - c.centre[0]) > 1e-9 || Math.abs(lo - c.centre[1]) > 1e-9)
    fail(`CENTRE ${c.cell}: js ${[la, lo]} vs py ${c.centre}`);
  try {
    if (mod.decodeCell(c.words) !== c.cell) fail(`DECODE ${c.words.join(' ')}`);
  } catch (e) { fail(`DECODE ${c.words.join(' ')}: ${e.message}`); }
}

for (const [la, lo] of fixture.outside)
  if (mod.cellAt(la, lo) !== null) fail(`OUTSIDE ${la},${lo} has a cell in js`);

for (const w of fixture.wrong) {
  let got = null;
  try { got = mod.decodeCell(w.words); } catch { /* refused */ }
  if (got !== w.cell) fail(`WRONG ${w.words.join(' ')}: js ${got} vs py ${w.cell}`);
}

if (mod.parsePhrase('  Cheeky, film FOLLOW banana ').length !== 4) fail('PARSE');

console.log(`uk phrase demo vs python reference: ${fixture.points.length} points, `
  + `${fixture.scramble.length} scrambles, ${fixture.wrong.length} wrong phrases`);
if (bad) { console.error(`FAIL: ${bad} problem(s)`); process.exit(1); }
console.log('OK: the lists, the mask, the scramble, cells, phrases and wrong words all match');
